const DICTS = { es, en };

function detect() {
  try {
    const saved = localStorage.getItem("tamiz.lang");
    if (saved && DICTS[saved]) return saved;
  } catch { /* storage blocked */ }
  return (navigator.language || "es").toLowerCase().startsWith("es") ? "es" : "en";
}

let current = detect();

export function lang() { return current; }

export function setLang(l) {
  current = DICTS[l] ? l : "es";
  try { localStorage.setItem("tamiz.lang", current); } catch { /* storage blocked */ }
}

function fill(text, params) {
  return text.replace(/\{(\w+)\}/g, (m, k) => (params && params[k] !== undefined && params[k] !== null ? String(params[k]) : m));
}

export function has(key) { return key in DICTS[current] || key in en; }

export function t(key, params) {
  // Singular forms: "key_one" is used when params.n === 1 and it exists.
  if (params && params.n === 1 && (DICTS[current][key + "_one"] ?? en[key + "_one"]) !== undefined) {
    key += "_one";
  }
  const text = DICTS[current][key] ?? en[key];
  if (text === undefined) return key;
  return fill(text, params);
}

// For codes coming from the server: use the translation when there is one,
// otherwise the detail the server sent, otherwise the code itself.
export function tCode(key, params = {}) {
  if (has(key)) return t(key, params);
  return params.detail || params.message || key.split(".").pop().replace(/_/g, " ");
}

export function tError(code, params = {}, message = "") {
  const key = "err." + code;
  if (has(key)) return t(key, { ...params, message });
  return message || code.replace(/_/g, " ");
}

export function tIssue(issue) {
  const key = "issue." + issue.code;
  if (has(key)) return t(key, issue.params || {});
  return issue.code.replace(/_/g, " ") + (issue.field ? ` (${issue.field})` : "");
}

export const dictionaries = DICTS;
